head.script:
scwin.onpageload = function() {
	// 통계 초기값 설정
	dm_stats.setJSON({
		totalCount: "0",
		activeCount: "0", 
		leftCount: "0",
		avgMinutes: "0"
	});

	// 초기 데이터 설정
	dm_search.set("scSessionId", "1001");

	// 데이터 로드
	setTimeout(function() {
		scwin.btn_search_onclick();
	}, 100);

	// 실시간 시계 시작
	scwin.startRealTimeClock();
};

// ===== 검색 기능 =====
scwin.btn_search_onclick = function() {
	scwin.loadDummyData();
};

scwin.loadDummyData = function() {
	var sessionId = dm_search.get("scSessionId") || "1001";
	var dummyData = scwin.getDummyDataBySession(sessionId);

	attendanceList.removeAll();

	if (dummyData && dummyData.length > 0) {
		attendanceList.setJSON(dummyData);
		scwin.updateStats(dummyData);
	} else {
		scwin.updateStats([]);
	}
};

scwin.getDummyDataBySession = function(sessionId) {
	var allData = {
		"1001": [
			{recordId: "9", sessionId: "1001", name: "김철수", email: "kim.cs@company.com", ipAddress: "192.168.1.10", joinTime: "2025-07-15 09:00:00", leaveTime: "2025-07-15 10:30:00", participationMinutes: "90", status: "퇴장완료"},
			{recordId: "10", sessionId: "1001", name: "이영희", email: "lee.yh@company.com", ipAddress: "192.168.1.11", joinTime: "2025-07-15 09:02:15", leaveTime: "2025-07-15 10:28:45", participationMinutes: "86", status: "퇴장완료"},
			{recordId: "11", sessionId: "1001", name: "박민수", email: "park.ms@company.com", ipAddress: "192.168.1.12", joinTime: "2025-07-15 09:05:30", leaveTime: "", participationMinutes: "-", status: "참여중"},
			{recordId: "15", sessionId: "1001", name: "윤서준", email: "yoon.sj@company.com", ipAddress: "192.168.1.16", joinTime: "2025-07-15 09:10:30", leaveTime: "", participationMinutes: "-", status: "참여중"}
		],
		"1002": [
			{recordId: "17", sessionId: "1002", name: "강지현", email: "kang.jh@school.edu", ipAddress: "10.0.0.20", joinTime: "2025-07-15 14:00:00", leaveTime: "2025-07-15 15:45:00", participationMinutes: "105", status: "퇴장완료"},
			{recordId: "19", sessionId: "1002", name: "임도윤", email: "lim.dy@school.edu", ipAddress: "10.0.0.22", joinTime: "2025-07-15 14:03:45", leaveTime: "", participationMinutes: "-", status: "참여중"},
			{recordId: "23", sessionId: "1002", name: "홍길동", email: "hong.gd@school.edu", ipAddress: "10.0.0.26", joinTime: "2025-07-15 14:12:30", leaveTime: "", participationMinutes: "-", status: "참여중"}
		],
		"1003": [
			{recordId: "24", sessionId: "1003", name: "이준호", email: "lee.jh@startup.co.kr", ipAddress: "172.16.0.10", joinTime: "2025-07-16 10:00:00", leaveTime: "2025-07-16 11:30:00", participationMinutes: "90", status: "퇴장완료"},
			{recordId: "27", sessionId: "1003", name: "정은비", email: "jung.eb@startup.co.kr", ipAddress: "172.16.0.13", joinTime: "2025-07-16 10:02:30", leaveTime: "", participationMinutes: "-", status: "참여중"}
		]
	};

	return allData[sessionId] || [];
};

// ===== 통계 업데이트 =====
scwin.updateStats = function(data) {
	var total = data.length;
	var active = 0;
	var left = 0;
	var totalMinutes = 0;
	var validCount = 0;

	for (var i = 0; i < data.length; i++) {
		if (data[i].status === "참여중") {
			active++;
		} else {
			left++;
		}

		if (data[i].participationMinutes !== "-" && data[i].participationMinutes !== "") {
			totalMinutes += parseInt(data[i].participationMinutes);
			validCount++;
		}
	}

	var avgMinutes = validCount > 0 ? Math.round(totalMinutes / validCount) : 0;

	dm_stats.set("totalCount", total);
	dm_stats.set("activeCount", active);
	dm_stats.set("leftCount", left);
	dm_stats.set("avgMinutes", avgMinutes);
};

// ===== CSV 다운로드 =====
scwin.btn_downloadCSV_onclick = function() {
	var sessionId = dm_search.get("scSessionId") || "전체";
	scwin.generateClientCSV(sessionId);
};

scwin.generateClientCSV = function(sessionId) {
	var data = attendanceList.getJSON();
	if (data.length === 0) {
		alert("다운로드할 데이터가 없습니다.");
		return;
	}

	var csvContent = '\ufeff'; // BOM for UTF-8
	csvContent += '번호,세션ID,참여자명,이메일,접속IP,입장시간,퇴장시간,참여시간(분),상태\n';

	for (var i = 0; i < data.length; i++) {
		var row = data[i];
		csvContent += (i + 1) + ',';
		csvContent += row.sessionId + ',';
		csvContent += row.name + ',';
		csvContent += row.email + ',';
		csvContent += row.ipAddress + ',';
		csvContent += row.joinTime + ',';
		csvContent += (row.leaveTime || '진행중') + ',';
		csvContent += (row.participationMinutes || '-') + ',';
		csvContent += row.status + '\n';
	}

	// 파일 다운로드
	var blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
	var link = document.createElement('a');
	var url = URL.createObjectURL(blob);
	link.setAttribute('href', url);
	link.setAttribute('download', 'attendance_session_' + sessionId + '_' + scwin.getCurrentDateTime() + '.csv');
	link.style.visibility = 'hidden';
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);

	alert('CSV 파일이 다운로드되었습니다!');
};

scwin.getCurrentDateTime = function() {
	var now = new Date();
	return now.getFullYear() + 
		   String(now.getMonth() + 1).padStart(2, '0') + 
		   String(now.getDate()).padStart(2, '0') + '_' +
		   String(now.getHours()).padStart(2, '0') + 
		   String(now.getMinutes()).padStart(2, '0') + 
		   String(now.getSeconds()).padStart(2, '0');
};

// ===== 이벤트 핸들러 =====
scwin.sel_sessionId_onchange = function() {
	scwin.btn_search_onclick();
};

scwin.btn_reset_onclick = function() {
	dm_search.setJSON({
		scSessionId: "",
		scName: "",
		scEmail: "",
		scJoinTime: ""
	});
	attendanceList.removeAll();
	dm_stats.setJSON({
		totalCount: "0",
		activeCount: "0", 
		leftCount: "0",
		avgMinutes: "0"
	});
	alert("초기화되었습니다!");
};

// ===== 실시간 시계 =====
scwin.startRealTimeClock = function() {
	setInterval(function() {
		var now = new Date();
		var timeStr = now.toLocaleTimeString('ko-KR');
		document.title = '출석 관리 시스템 - ' + timeStr;
	}, 1000);
};

// ===== 서비스 콜백 =====
scwin.wf_searchAttendance_onprocess = function(requestObj, responseObj) {
	if (responseObj.process == "success") {
		scwin.updateStats(attendanceList.getJSON());
		alert("출석 현황을 조회했습니다.");
	} else {
		alert("조회 중 오류가 발생했습니다.");
	}
};
